import{_ as i,p as a,q as e,Y as l}from"./framework-e1bed10d.js";const r={},h=l('<h1 id="_18分库分表" tabindex="-1"><a class="header-anchor" href="#_18分库分表" aria-hidden="true">#</a> 18分库分表</h1><p>随着互联网及移动互联网的发展，应用系统的数据量也是成指数式增长，若采用单数据库进行数据存 储，存在以下性能瓶颈：</p><ol><li><p>IO瓶颈：热点数据太多，数据库缓存不足，产生大量磁盘IO，效率较低。 请求数据太多，带宽 不够，网络IO瓶颈</p></li><li><p>CPU瓶颈：排序、分组、连接查询、聚合统计等SQL会耗费大量的CPU资源，请求数太多，CPU出 现瓶颈</p></li></ol><p>为了解决上述问题，我们需要对数据库进行分库分表处理</p><p>分库分表的中心思想都是将数据分散存储，使得单一数据库/表的数据量变小来缓解单一数据库的性能问题，从而达到提升数据库性能的目的</p><h2 id="拆分方式" tabindex="-1"><a class="header-anchor" href="#拆分方式" aria-hidden="true">#</a> 拆分方式</h2><h3 id="垂直分库" tabindex="-1"><a class="header-anchor" href="#垂直分库" aria-hidden="true">#</a> 垂直分库</h3><p>以表为依据，根据业务将不同表拆分到不同库中</p><p>特点：</p><ul><li>每个库的表结构都不一样</li><li>每个库的数据也不一样</li><li>所有库的并集是全量数据</li></ul><h3 id="垂直分表" tabindex="-1"><a class="header-anchor" href="#垂直分表" aria-hidden="true">#</a> 垂直分表</h3><p>以字段为依据，按照一定策略，将一个库的数据拆分到多个库中</p><p>特点：</p><ul><li>每个库的表结构都一样</li><li>每个库的数据都不一样</li><li>所有库的并集是全量数据</li></ul><h3 id="水平分库" tabindex="-1"><a class="header-anchor" href="#水平分库" aria-hidden="true">#</a> 水平分库</h3><p>以字段为依据，按照一定策略，将一个库的数据拆分到多个库中</p><p>特点：</p><ul><li>每个库的表结构都一样</li><li>每个库的数据都不一样</li><li>所有库的并集是全量数据</li></ul><h3 id="水平分表" tabindex="-1"><a class="header-anchor" href="#水平分表" aria-hidden="true">#</a> 水平分表</h3><p>以字段为依据，按照一定策略，将一个表的数据拆分到多个表中</p><p>特点：</p><ul><li>每个表的表结构都一样</li><li>每个表的数据都不一样</li><li>所有表的并集是全量数据</li></ul>',22),d=[h];function t(n,p){return a(),e("div",null,d)}const s=i(r,[["render",t],["__file","18sub-db.html.vue"]]);export{s as default};
